import json
import re
from docx import Document

def fill_offer_letter(template_path, data_path, output_path):
    with open(data_path, 'r') as f:
        data = json.load(f)

    doc = Document(template_path)

    relocation_enabled = data.get("RELOCATION_PACKAGE") == "Yes"

    def replace_in_text(text, data):
        pattern = r'\{\{([A-Z0-9_]+)\}\}'
        new_text = text
        for match in re.finditer(pattern, text):
            placeholder = match.group(0)
            key = match.group(1)
            if key in data:
                new_text = new_text.replace(placeholder, str(data[key]))
        return new_text

    def process_paragraph(para, data):
        text = para.text
        new_text = replace_in_text(text, data)
        if new_text != text:
            if para.runs:
                para.runs[0].text = new_text
                for run in para.runs[1:]:
                    run.text = ''
            else:
                para.text = new_text

    # Handle multi-paragraph conditional: {{IF_RELOCATION}} ... {{END_IF_RELOCATION}}
    # We'll first find the indices of paragraphs containing these markers.

    start_marker = "{{IF_RELOCATION}}"
    end_marker = "{{END_IF_RELOCATION}}"

    paragraphs = doc.paragraphs
    start_idx = -1
    end_idx = -1

    for i, para in enumerate(paragraphs):
        if start_marker in para.text:
            start_idx = i
        if end_marker in para.text:
            end_idx = i

    if start_idx != -1 and end_idx != -1:
        if relocation_enabled:
            # Keep content, just remove markers
            # Remove start marker from its paragraph
            p_start = paragraphs[start_idx]
            p_start.text = p_start.text.replace(start_marker, "")
            # If paragraph is now empty, we might want to keep it or not. 
            # Usually better to just clear text in runs to keep formatting if any.
            if p_start.runs:
                p_start.runs[0].text = p_start.text
                for run in p_start.runs[1:]:
                    run.text = ''

            # Remove end marker
            p_end = paragraphs[end_idx]
            p_end.text = p_end.text.replace(end_marker, "")
            if p_end.runs:
                p_end.runs[0].text = p_end.text
                for run in p_end.runs[1:]:
                    run.text = ''
        else:
            # Remove everything between start_idx and end_idx inclusive
            # Note: doc.paragraphs is not a list you can just pop from and expect it to work easily for document structure.
            # A better way is to clear the text of these paragraphs.
            for i in range(start_idx, end_idx + 1):
                p = paragraphs[i]
                p.text = ""
                for run in p.runs:
                    run.text = ""

    # Process all paragraphs for normal placeholders
    for para in doc.paragraphs:
        process_paragraph(para, data)

    # Process tables
    def process_table(table, data):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    process_paragraph(para, data)
                for nested_table in cell.tables:
                    process_table(nested_table, data)

    for table in doc.tables:
        process_table(table, data)

    # Process headers and footers
    for section in doc.sections:
        for para in section.header.paragraphs:
            process_paragraph(para, data)
        for para in section.footer.paragraphs:
            process_paragraph(para, data)

    doc.save(output_path)

if __name__ == "__main__":
    fill_offer_letter('offer_letter_template.docx', 'employee_data.json', 'offer_letter_filled.docx')
